package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.service.settings.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class BacklogHistoryObservationServiceTest extends BacklogNativeHistoryStoreTest{
 BacklogHistoryObservationService source(Fixture f,JdbcBacklogHistory db,DispatchReadinessService readiness,SettingsJdbcStore settings){Instant born=f.clock.instant();return new BacklogHistoryObservationService(db,readiness,settings,f.tx,f.clock,()->Duration.between(born,f.clock.instant()).toNanos());}
 SettingsJdbcStore settings(boolean paused){var settings=mock(SettingsJdbcStore.class);when(settings.current()).thenReturn(new SettingsUpdateService.Current(1,List.of("Fictional keyword"),List.of(),paused,null,MonitoringFixtures.complete(),true));return settings;}
 void save(Fixture f,BacklogHistoryObservationService source,BacklogHistoryObservationService.Observation facts,int n){String hash="d".repeat(32);f.writes.execute(new SharedWriteExecutor.ActionContext("backlog-sample:"+hash+":"+n*60,"ops_"+hash,null),k->null,k->{source.save(facts);return true;});}
 @Test void actualEmptyQueueRequiresNativeWitnessAndUnavailableCurrentProofIsNotZero(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){var db=new JdbcBacklogHistory(f.source,scope);var ready=mock(DispatchReadinessService.class);var source=source(f,db,ready,settings(false));var missing=source.acquire();assertNotNull(missing);assertNull(missing.facts().mutation());assertTrue(missing.facts().entries().isEmpty());String hash="e".repeat(32);write(f,"api-sample:"+hash+":60","ops_"+hash);f.clock.now=f.clock.now.plusSeconds(60);var actual=source.acquire();assertNotNull(actual.facts().mutation());assertTrue(actual.facts().entries().isEmpty());verifyNoInteractions(ready);assertEquals("BacklogHistoryObservation[redacted]",actual.toString());}}
 @Test void actualOriginalHistoryKeepsUnknownPrefixThenOnlyProvesStableReadyUnpausedIntervals(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){var db=new JdbcBacklogHistory(f.source,scope);var root=root(f,db);f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-queue","fictional-root",null),k->null,k->{f.sql.update("UPDATE jobs SET state='queued',revision=revision+1 WHERE id='fictional-root'");return true;});var ready=mock(DispatchReadinessService.class);when(ready.preflight(root.id())).thenReturn(true);var source=source(f,db,ready,settings(false));f.clock.now=f.clock.now.plusSeconds(60);var first=source.acquire();assertNull(first.facts().entries().getFirst().spans().getFirst().ready());save(f,source,first,1);f.clock.now=f.clock.now.plusSeconds(60);var second=source.acquire();assertEquals(2,second.facts().entries().getFirst().spans().size());assertTrue(second.facts().entries().getFirst().spans().getLast().ready());assertFalse(second.facts().entries().getFirst().spans().getLast().globallyPaused());save(f,source,second,2);write(f,"fictional-business-change","fictional-business");f.clock.now=f.clock.now.plusSeconds(60);var gap=source.acquire();assertNull(gap.facts().entries().getFirst().spans().getLast().ready());save(f,source,gap,3);assertEquals(3,rr(f,()->db.read(root)).revision());}}
 @Test void currentPauseExcludesKnownIntervalsAndFutureEligibleTimeIsSplitExactly(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){var db=new JdbcBacklogHistory(f.source,scope);var root=root(f,db);f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-future-queue","fictional-root",null),k->null,k->{f.sql.update("UPDATE jobs SET state='queued',eligible_at=?,revision=revision+1 WHERE id='fictional-root'",java.sql.Timestamp.from(f.clock.instant().plusSeconds(90)));return true;});var ready=mock(DispatchReadinessService.class);when(ready.preflight(root.id())).thenReturn(true);var source=source(f,db,ready,settings(true));f.clock.now=f.clock.now.plusSeconds(60);save(f,source,source.acquire(),1);f.clock.now=f.clock.now.plusSeconds(60);var result=source.acquire();var spans=result.facts().entries().getFirst().spans();assertEquals(3,spans.size());assertFalse(spans.get(1).ready());assertTrue(spans.get(2).ready());assertTrue(spans.get(2).globallyPaused());assertEquals(root.createdAt().plusSeconds(90),spans.get(2).start());}}
 @Test void missingReadonlyReadinessProofAndDamagedHistoryStillExposeOnlyActualWallAge(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){var db=new JdbcBacklogHistory(f.source,scope);var root=root(f,db);f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-queue-unknown","fictional-root",null),k->null,k->{f.sql.update("UPDATE jobs SET state='queued',revision=revision+1 WHERE id='fictional-root'");return true;});var ready=mock(DispatchReadinessService.class);when(ready.preflight(root.id())).thenThrow(new IllegalStateException("Fictional original INPUT proof missing"));var source=source(f,db,ready,settings(false));f.clock.now=f.clock.now.plusSeconds(60);var first=source.acquire();assertNotNull(first);assertNull(first.changes().getFirst().next().ready());save(f,source,first,1);f.sql.update("UPDATE runtime_settings SET value_json='{}' WHERE setting_key=?",JdbcBacklogHistory.key(root.id()));f.clock.now=f.clock.now.plusSeconds(60);var damaged=source.acquire();assertNotNull(damaged);assertNull(damaged.facts().entries().getFirst().spans());assertTrue(damaged.changes().isEmpty());assertEquals(root.createdAt(),damaged.facts().entries().getFirst().createdAt());}}
 @Test void transactionClockRollbackAndNativeMonotonicMismatchAreUnknownAndNoHistoryIsWritten(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){var db=new JdbcBacklogHistory(f.source,scope);var source=source(f,db,mock(DispatchReadinessService.class),settings(false));assertNotNull(source.acquire());f.clock.now=f.clock.now.minusSeconds(1);assertNull(source.acquire());var outer=new org.springframework.transaction.support.TransactionTemplate(f.tx);assertThrows(IllegalStateException.class,()->outer.execute(s->source.acquire()));var mismatched=new BacklogHistoryObservationService(db,mock(DispatchReadinessService.class),settings(false),f.tx,f.clock,()->0);assertNotNull(mismatched.acquire());f.clock.now=f.clock.now.plusSeconds(3);assertNull(mismatched.acquire());}}
 @Test void queryDurationRemainsUnknownBeforeTheNextProvenInterval(){
  var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){
   var db=new JdbcBacklogHistory(f.source,scope);var root=root(f,db);
   f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-query-bracket","fictional-root",null),k->null,k->{f.sql.update("UPDATE jobs SET state='queued',revision=revision+1 WHERE id='fictional-root'");return true;});
   var ready=mock(DispatchReadinessService.class);var calls=new java.util.concurrent.atomic.AtomicInteger();
   when(ready.preflight(root.id())).thenAnswer(invocation->{if(calls.incrementAndGet()==1)f.clock.now=f.clock.now.plusMillis(500);return true;});
   var source=source(f,db,ready,settings(false));f.clock.now=f.clock.now.plusSeconds(60);
   var first=source.acquire();assertNotNull(first);assertEquals(first.facts().readAt().plusMillis(500),first.changes().getFirst().next().verifiedAfter());save(f,source,first,1);
   f.clock.now=root.createdAt().plusSeconds(120);var second=source.acquire();assertNotNull(second);
   var spans=second.facts().entries().getFirst().spans();assertEquals(2,spans.size());assertNull(spans.getFirst().ready());assertEquals(first.changes().getFirst().next().verifiedAfter(),spans.getLast().start());assertTrue(spans.getLast().ready());assertFalse(spans.getLast().globallyPaused());
  }
 }
}
